def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    if row < 0 or row >= 64 or col < 0 or col >= 64:
        return board

    char = board[row][col]
    if char == 'g':
        board[row][col] = 'N'
        if col > 0 and board[row][col-1] == 'g':
            board[row][col-1] = 'N'
        if col < 63 and board[row][col+1] == 'g':
            board[row][col+1] = 'N'
        if row > 0 and board[row-1][col] == 'g':
            board[row-1][col] = 'N'
        if row < 63 and board[row+1][col] == 'g':
            board[row+1][col] = 'N'
    elif char == 'W':
        board[row][col] = 'G'

    return ["".join(row) for row in board]
